from typing import Any, Literal, Union
from pydantic import BaseModel, ConfigDict, Field, TypeAdapter, field_validator

KNOWN_BLOCKS = {"tool-input", "tool-output"}
KNOWN_MESSAGES = {"user-message", "assistant-response", "compaction"}


class Loose(BaseModel):
    """Duck typing. Extra keys are data, not errors."""
    model_config = ConfigDict(extra="allow")


class TextPart(Loose):
    type: Literal["text"]
    text: str


class ToolInputBlock(Loose):
    type: Literal["tool-input"]
    name: str = Field(min_length=1)
    id: str | None = None
    native_tool_call_id: str | None = None
    native_content_index: int | None = None
    input: dict[str, Any] | None = None   # some tools nest their arguments here
    # every remaining key is a tool argument, reached through model_extra


class ToolOutputBlock(Loose):
    type: Literal["tool-output"]
    name: str = Field(min_length=1)
    id: str | None = None
    native_tool_call_id: str | None = None
    is_error: bool = False
    content: str | list[TextPart | Loose] = ""


class OpaqueBlock(Loose):
    """Thinking blocks, subagent tasks, anything else. Passthrough."""
    type: str

    @field_validator("type")
    @classmethod
    def must_not_shadow_a_known_block(cls, value: str) -> str:
        if value in KNOWN_BLOCKS:
            raise ValueError(f"malformed {value} block")
        return value


ContentItem = Union[str, ToolInputBlock, ToolOutputBlock, OpaqueBlock]


class KnownMessage(Loose):
    type: Literal["user-message", "assistant-response", "compaction"]
    original_index: int
    content: list[ContentItem]
    role: str | None = None
    model: str | None = None
    timestamp: str | None = None
    native_entry_id: str | None = None


class ForeignMessage(Loose):
    type: str

    @field_validator("type")
    @classmethod
    def must_not_shadow_a_known_message(cls, value: str) -> str:
        if value in KNOWN_MESSAGES:
            raise ValueError(f"malformed {value} message")
        return value


Transcript = TypeAdapter(list[Union[KnownMessage, ForeignMessage]])

