def _resolve_exact_session_identifier(
    identifier: str,
    conversation_files: Iterable[Path],
) -> Path | None:
    """Resolve a single-token identifier against the unified session pool."""
    if len(identifier.split()) != 1:
        return None

    # Fast path 1: Exact stem or filename match (Claude)
    for conv_file in conversation_files:
        if conv_file.stem == identifier or conv_file.name == identifier:
            return conv_file

    # Fast path 2: Stem contains identifier (PI/Codex)
    for conv_file in conversation_files:
        if identifier in conv_file.stem:
            if get_native_session_id(conv_file) == identifier:
                return conv_file

    # Slow path: Fallback for renamed files
    for conv_file in conversation_files:
        if get_native_session_id(conv_file) == identifier:
            return conv_file

    return None

def _extract_field_from_jsonl(
    file_path: Path, entry_type: str, field_name: str
) -> list[str]:
    """Extract field values from a jsonl file without loading it entirely."""
    values = []
    try:
        with open(file_path, "r", encoding="utf-8") as f:
            for line in f:
                if not line.startswith("{"):
                    continue
                # Fast path: skip JSON parsing if entry_type isn't in the raw string
                if f'"{entry_type}"' not in line:
                    continue
                try:
                    entry = json.loads(line)
                    if isinstance(entry, dict) and entry.get("type") == entry_type:
                        if value := entry.get(field_name):
                            values.append(value)
                except json.JSONDecodeError:
                    pass
        return values
    except OSError:
        return []
